import csv
import re
import io

data = """"Eski Suakin Adası (Cinlerin Şehri)","Kızıldeniz Eyaleti","Sudan","Kızıldeniz kıyısında mercanlardan inşa edilmiş ancak uzun süre önce terk edilerek çürümeye yüz tutmuş devasa hayalet liman şehri. Daracık yıkık sokaklarında esen sıcak çöl rüzgarı ve efsanelere göre şehri ele geçiren Cin krallarının yarattığı o görünmez, yutucu astral enerji sizi felç eder.",5"Meroe Piramitleri (Kara Firavunların Mezarları)","Nil Vadisi","Sudan","Kızgın çöl kumlarının ortasında yükselen ve 'Kara Firavunlar' olarak bilinen antik Kuş Krallığı'na ait onlarca sivri uçlu, kapkaranlık piramit. Gece yarısı çölün mutlak sessizliğinde piramitlerin altından gelen o ağır, kadim ölüm frekansı ve mumyalanmış kralların yalnızlığı auranızı sarsar.",4"Kober Hapishanesi (Siyasi İnfaz Odaları)","Hartum","Sudan","İngiliz sömürge döneminde inşa edilen ve onyıllar boyunca diktatörlüklerin sayısız muhalifi işkenceden geçirip idam ettiği acımasız cezaevi. İnfaz avlularına sinmiş o sülfürik kan kokusu ve karanlık tecrit hücrelerinde aklını yitiren mahkumların araftaki feryatları zihninizi daraltır.",5"Nuba Dağları (Bombardıman Mağaraları)","Güney Kordofan","Sudan","Uzun süren iç savaş boyunca halkın sığınak olarak kullandığı ancak birçoğunun içinde açlıktan veya bombardımandan topluca can verdiği devasa karanlık mağaralar. Oksijensiz kayalıkların arasına mühürlenmiş o saf savaş travması ve kayıpların toplu klostrofobik kederi nefesinizi keser.",5"Omdurman Savaş Meydanı (Süvari Mezarlığı)","Omdurman","Sudan","1898 yılında İngiliz makineli tüfeklerine karşı kılıçlarla saldıran 10 binden fazla Mehdi dervişinin saatler içinde katledildiği o kanlı düzlük. Çöl gecelerinde kumların altından yankılanan savaş naraları ve toprağa işlemiş olan o ezici, tek taraflı katliam anksiyetesi insanı transa sokar.",5"Sednaya Hapishanesi (İnsan Mezbahası)","Şam Yakınları","Suriye","Modern tarihin en korkunç, en vahşi ve en sistematik işkence-infaz merkezlerinden biri olarak bilinen ve on binlerce insanın sessizce yok edildiği o devasa 'mezebeha'. Beton dehlizlerinden sızan o tarifsiz, akıl almaz devlet terörü ve kurbanların duvarlara kazıdığı mutlak dehşet ruhunuzu ezer.",5"Tadmur (Palmira) Eski Zindanları","Palmira","Suriye","Çölün ortasında, mahkumların zehirli akreplerle bir arada tutulduğu ve 1980'lerde tek bir gecede yüzlerce esirin hücrelerinde taranarak katledildiği o efsanevi vahşet kampı. Yıkıntıların arasında esen kavurucu rüzgarın taşıdığı taze kan kokusu ve araftaki ruhların dinmeyen işkence feryadı auranızı parçalar.",5"Guta Harabeleri (Sarin Gazı Bölgeleri)","Doğu Guta","Suriye","İç savaşın en karanlık günlerinde kimyasal silah saldırısına uğrayan ve uykularında boğularak ölen binlerce sivile mezar olan o devasa, sessiz ve zehirli harabe şehir. Boş sokaklarında havaya asılı kalan o sinsi, kimyasal ölüm anksiyetesi ve oksijensiz çırpınanların o toplu kederi nefesinizi keser.",5"Krak des Chevaliers (Şövalyeler Kalesi)","Humus","Suriye","Haçlı Seferleri döneminde inşa edilen, asırlarca kuşatmalara, katliamlara ve en son iç savaş çatışmalarına sahne olmuş devasa tapınak şövalyeleri kalesi. Karanlık zindanlarından ve devasa kulelerinden yansıyan o ağır, Orta Çağ savaş paranoyası ve kanlı şövalye silüetleri zihninizi bulandırır.",4"Emevi Camii Savaş Harabeleri","Halep","Suriye","Bin yıllık kadim tarihine rağmen yakın zamandaki savaşta avlusu çatışma alanına dönen ve büyük yıkım yaşayan o kutsal ibadethane. Kurşun deşikli antik sütunlarının arasında gezinirken, minareden yayılan o devasa, melankolik ağıt ve şehrin parçalanmış ruhu kalbinizi derinden sıkar.",4"Zanzibar Taş Şehir (Eski Köle Pazarı)","Zanzibar","Tanzanya","Doğu Afrika'nın en büyük ve en acımasız köle ticaret merkezi olan, yüz binlerce insanın zincirlenerek kırbaçlandığı o karanlık taş meydanlar ve yeraltı hücreleri. Oksijensiz zindanlardan yükselen o ağır, toplu kölelik feryadı ve koparılan ailelerin nesiller boyu süren travması auranızı felç eder.",5"Changuu Adası (Mahkum ve Karantina Zindanı)","Zanzibar Yakınları","Tanzanya","İsyankar kölelerin hapsedildiği ve daha sonra ölümcül sarı humma hastaları için tecrit adasına dönüştürülen o rutubetli, okyanus ortasındaki sömürge hapishanesi. Çürük duvarlara vuran dalga seslerine karışan hastalıklı öksürükler ve yalıtılmış keder frekansı insanı deliliğe sürükler.",5"Amboni Mağaraları (Kayıp Ruhlar Labirenti)","Tanga","Tanzanya","Doğu Afrika'nın en büyük kireçtaşı mağara sistemi olan ve yerel kabilelerin yüzyıllardır antik ruhlara (Şeytanlara) adaklar sunduğu bu zifiri karanlık labirent. Sonunun nereye vardığı bilinmeyen dehlizlerde kaybolan insanların fısıltıları ve mağaranın o ezici, kadim pagan manyetizması nefesinizi keser.",4"Kondoa İrangi Kaya Sığınakları","Dodoma","Tanzanya","Binlerce yıl öncesine ait tuhaf şamanik ayinleri ve uzaylılara benzeyen figürleri barındıran sarp kaya sığınakları. Gece yarısı rüzgarın kayalara çarparak çıkardığı o ilkel, ritmik davul sesleri ve arazinin altından gelen o vahşi animizm frekansı zihninizi daraltır.",4"Ngozi Gölü (Meteor Krateri Cansız Suları)","Mbeya","Tanzanya","Devasa bir volkanik kraterin içinde yer alan, yerel halkın derinliklerinde şeytani bir varlığın yaşadığına inandığı ve etrafında insanların kaybolduğu kapkara göl. Zifiri suların yaydığı o soğuk, yutucu ölüm enerjisi ve ormanın içine gizlenmiş olan o mutlak izole sessizlik ruhunuzu dondurur.",4"""

# Split by fixing the missing newline before a quote after a number
formatted_data = re.sub(r'(\d)"', r'\1\n"', data)

reader = csv.reader(io.StringIO(formatted_data))
with open('perili_mekanlar.csv', 'a', encoding='utf-8', newline='') as f:
    writer = csv.writer(f)
    for row in reader:
        # Avoid empty lines
        if not row:
            continue
        if len(row) == 5:
            row.append('') # resim_url
        writer.writerow(row)

print("Sudan, Suriye ve Tanzanya kayitlari eklendi.")
